  data.contexts['file-actions']={'Attiva':['Enable','Activar','Activer','Aktivieren']};
  data.pattern(/^(\d+) file selezionati$/,['$1 files selected','$1 archivos seleccionados','$1 fichiers sélectionnés','$1 Dateien ausgewählt']);
  data.pattern(/^Eliminare i (\d+) file selezionati\?$/,['Delete the $1 selected files?','¿Eliminar los $1 archivos seleccionados?','Supprimer les $1 fichiers sélectionnés ?','Die $1 ausgewählten Dateien löschen?']);
  data.pattern(/^(\d+) file attivati\.$/,['$1 files enabled.','$1 archivos activados.','$1 fichiers activés.','$1 Dateien aktiviert.']);
  data.pattern(/^(\d+) file disattivati\.$/,['$1 files disabled.','$1 archivos desactivados.','$1 fichiers désactivés.','$1 Dateien deaktiviert.']);
  data.pattern(/^(\d+) file spostati nel Cestino\.$/,['$1 files moved to Recycle Bin.','$1 archivos movidos a la Papelera.','$1 fichiers déplacés dans la Corbeille.','$1 Dateien in den Papierkorb verschoben.']);
  data.pattern(/^Operazione parziale: (\d+) file non modificati\.$/,['Partial operation: $1 files unchanged.','Operación parcial: $1 archivos sin modificar.','Opération partielle : $1 fichiers inchangés.','Vorgang teilweise abgeschlossen: $1 Dateien unverändert.']);
  data.pattern(/^Esiste già un file chiamato “(.+)”\. Nessun file è stato sovrascritto\.$/,['A file named “$1” already exists. No file was overwritten.','Ya existe un archivo llamado “$1”. No se ha sobrescrito ningún archivo.','Un fichier nommé « $1 » existe déjà. Aucun fichier n’a été écrasé.','Eine Datei namens „$1“ existiert bereits. Keine Datei wurde überschrieben.']);
  data.pattern(/^Seleziona (.+)$/,['Select $1','Seleccionar $1','Sélectionner $1','$1 auswählen']);
  data.pattern(/^(\d+) file$/,['$1 files','$1 archivos','$1 fichiers','$1 Dateien']);
  data.pattern(/^Eliminare “(.+)”\?$/,['Delete “$1”?','¿Eliminar “$1”?','Supprimer « $1 » ?','„$1“ löschen?']);
  data.pattern(/^Archiviare “(.+)”\?$/,['Archive “$1”?','¿Archivar “$1”?','Archiver « $1 » ?','„$1“ archivieren?']);
  data.pattern(/^Servizio remoto: HTTP (\d+)(\. Riprova più tardi\.)?$/,['Remote service: HTTP $1. Try again later.','Servicio remoto: HTTP $1. Reintenta más tarde.','Service distant : HTTP $1. Réessayez plus tard.','Remotedienst: HTTP $1. Versuche es später erneut.']);
  data.pattern(/^Download fallito \(HTTP (\d+)\)\.$/,['Download failed (HTTP $1).','Descarga fallida (HTTP $1).','Téléchargement échoué (HTTP $1).','Download fehlgeschlagen (HTTP $1).']);
  data.pattern(/^Java (\d+) non disponibile dal servizio Adoptium\.$/,['Java $1 unavailable from Adoptium.','Java $1 no disponible en Adoptium.','Java $1 indisponible sur Adoptium.','Java $1 ist bei Adoptium nicht verfügbar.']);
  data.pattern(/^(\S+) GB liberi sul sistema$/,['$1 GB free on system','$1 GB libres en el sistema','$1 Go libres sur le système','$1 GB im System frei']);
  data.pattern(/^(\S+) GB disponibili sul PC$/,['$1 GB available on PC','$1 GB disponibles en el PC','$1 Go disponibles sur le PC','$1 GB auf dem PC verfügbar']);
  data.pattern(/^(\d+) GB · Modpack$/,['$1 GB · Modpacks','$1 GB · Modpacks','$1 Go · Modpacks','$1 GB · Modpacks']);
  data.pattern(/^(\d+) server attiv[oi] · Il tuo PC ospita l’avventura$/,['$1 active server(s) · Your PC hosts the adventure','$1 servidor(es) activo(s) · Tu PC aloja la aventura','$1 serveur(s) actif(s) · Votre PC héberge l’aventure','$1 aktive Server · Dein PC hostet das Abenteuer']);
  data.pattern(/^(Mod|Plugin) del server$/,['Server $1','$1 del servidor','$1 du serveur','Server-$1']);
  data.pattern(/^(\d+) file importati\.$/,['$1 files imported.','$1 archivos importados.','$1 fichiers importés.','$1 Dateien importiert.']);
  data.pattern(/^Apri (.+)$/,['Open $1','Abrir $1','Ouvrir $1','$1 öffnen']);
  data.pattern(/^Elimina server (.+)$/,['Delete server $1','Eliminar servidor $1','Supprimer le serveur $1','Server $1 löschen']);
  data.pattern(/^(.+)(\. Per cambiare software o versione crea un nuovo server: eviterai incompatibilità e danni al mondo\.)$/,['$1. Create a new server to change platform or version and avoid incompatibility or world damage.','$1. Crea un servidor nuevo para cambiar de software o versión y evitar incompatibilidades o daños.','$1. Créez un nouveau serveur pour changer de logiciel ou de version et éviter les dégâts.','$1. Erstelle zum Wechsel von Software oder Version einen neuen Server, um Inkompatibilitäten und Weltschäden zu vermeiden.']);
